namespace MyApp.Evals;

internal static class EvalConstants
{
    public const string StoragePath = ".eval-results";
    public const string EndpointEnvVar = "AZURE_OPENAI_ENDPOINT";
    public const string DeploymentEnvVar = "AZURE_OPENAI_DEPLOYMENT";
}

using Azure.AI.Inference;
using Azure.Identity;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

internal static class EvalSetup
{
    internal static ReportingConfiguration CreateReportingConfiguration(
        string runName,
        IEnumerable<IEvaluator>? additionalEvaluators = null)
    {
        var endpoint = Environment.GetEnvironmentVariable(EvalConstants.EndpointEnvVar)
            ?? throw new InvalidOperationException($"{EvalConstants.EndpointEnvVar} must be set.");
        var deployment = Environment.GetEnvironmentVariable(EvalConstants.DeploymentEnvVar)
            ?? "gpt-4o-mini";

        var chatClient = new ChatCompletionsClient(
                new Uri(endpoint),
                new DefaultAzureCredential())
            .AsChatClient(deployment);

        var evaluators = new List<IEvaluator>
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        if (additionalEvaluators is not null)
        {
            evaluators.AddRange(additionalEvaluators);
        }

        var storage = new DiskBasedReportingStorage(EvalConstants.StoragePath);

        return new ReportingConfiguration(
            storage,
            chatClient,
            evaluators,
            chatConfiguration: new ChatConfiguration(chatClient),
            runName: runName);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Telemetry mode: validates that the agent emits expected OpenTelemetry
/// traces and metrics during a conversation turn.
/// </summary>
[TestClass]
public class TelemetryTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration("telemetry");
    }

    [TestMethod]
    public async Task Agent_EmitsTokenUsageMetrics()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Agent_EmitsTokenUsageMetrics));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        Assert.IsTrue(
            response.Usage?.TotalTokenCount > 0,
            "Expected token usage to be reported.");

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Agent_RespondsWithinLatencyBudget()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Agent_RespondsWithinLatencyBudget));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Summarize the benefits of exercise in one sentence.")
        };

        var sw = System.Diagnostics.Stopwatch.StartNew();
        var response = await chatClient.GetResponseAsync(messages);
        sw.Stop();

        messages.AddRange(response.Messages);

        Assert.IsTrue(
            sw.ElapsedMilliseconds < 30_000,
            $"Response took {sw.ElapsedMilliseconds}ms, exceeding 30s budget.");

        await scenario.EvaluateAsync(messages);
    }
}

