/// <summary>
/// Quality mode: evaluates coherence, relevance, fluency, and groundedness
/// of agent responses using LLM-as-judge scoring.
/// </summary>
[TestClass]
public class QualityTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        s_config = EvalSetup.CreateReportingConfiguration("quality");
    }

    [TestMethod]
    public async Task Coach_ProvidesRelevantGuidance()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Coach_ProvidesRelevantGuidance));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "I want to improve my public speaking skills. What should I focus on first?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Coach_MaintainsCoherenceInMultiTurn()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Coach_MaintainsCoherenceInMultiTurn));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "I struggle with time management at work.")
        };

        var response1 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "Can you elaborate on the first suggestion?"));
        var response2 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response2.Messages);

        await scenario.EvaluateAsync(messages);
    }

