internal static class EvalSetup
{
    internal static ReportingConfiguration CreateReportingConfiguration(
        string runName,
        IEnumerable<IEvaluator>? additionalEvaluators = null)
    {
        var endpoint = Environment.GetEnvironmentVariable(EvalConstants.EndpointEnvVar)
            ?? throw new InvalidOperationException($"{EvalConstants.EndpointEnvVar} must be set.");
        var deployment = Environment.GetEnvironmentVariable(EvalConstants.DeploymentEnvVar)
            ?? "gpt-4o-mini";

        var chatClient = new ChatCompletionsClient(
                new Uri(endpoint),
                new DefaultAzureCredential())
            .AsChatClient(deployment);

        var evaluators = new List<IEvaluator>
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        if (additionalEvaluators is not null)
        {
            evaluators.AddRange(additionalEvaluators);
        }

        var storage = new DiskBasedReportingStorage(EvalConstants.StoragePath);

        return new ReportingConfiguration(
            storage,
            chatClient,
            evaluators,
            chatConfiguration: new ChatConfiguration(chatClient),
            runName: runName);
    }
}

