/// <summary>
/// Compare mode: runs the same prompts with a configurable run name so that
/// results from different models or configurations can be compared side-by-side
/// in the evaluation report.
/// </summary>
[TestClass]
public class CompareTests
{
    private static ReportingConfiguration? s_config;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        // Run name incorporates the deployment so results are grouped per model.
        var deployment = Environment.GetEnvironmentVariable(EvalConstants.DeploymentEnvVar)
            ?? "gpt-4o-mini";
        s_config = EvalSetup.CreateReportingConfiguration($"compare-{deployment}");
    }

    [TestMethod]
    public async Task Compare_CoachingResponse_Quality()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Compare_CoachingResponse_Quality));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "How can I build a daily exercise habit?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Compare_MultiTurn_Quality()
    {
        await using var scenario = await s_config!.CreateScenarioRunAsync(
            scenarioName: nameof(Compare_MultiTurn_Quality));

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful coaching assistant."),
            new(ChatRole.User, "I want to learn a new programming language.")
        };

        var response1 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response1.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "Which one would you recommend for data science?"));
        var response2 = await chatClient.GetResponseAsync(messages);
        messages.AddRange(response2.Messages);

        await scenario.EvaluateAsync(messages);
    }
}

